window.STORY_CHAPTERS["c9228671dcb8d96ab"]={"id":"c9228671dcb8d96ab","lines":[{"uid":"talk.vc.home_event_alice_uw_sleeping_12#originalText","id":"talk.vc.home_event_alice_uw_sleeping_12","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"月亮上住着兔子吗？你的世界那边有着很有趣的故事呢。","en":"There are rabbits on the moon? Your world sure has some interesting stories. ","ja":"月にウサギがいるのですかお前の世界には、面白い逸話があるのですね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_13#originalText","id":"talk.vc.home_event_alice_uw_sleeping_13","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"有好好把点心给出去了呢！虽然也有点想见见那些孩子会做出什么样的恶作剧呢。","en":"Of course I passed out the sweets. Even though I feel like I wanted to see those kid's trick...","ja":"ちゃんと菓子を渡しましたよあの子たちのイタズラも見たかったような気がしますが"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_15#originalText","id":"talk.vc.home_event_alice_uw_sleeping_15","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今晚是「圣诞夜」呢。不管由来为何，能和你度过这重要的夜晚，我很开心。","en":"It's Christmas Eve. I may not know the meaning of this day, but I'm happy I get to spend it with you.","ja":"今宵は「聖夜」なのですね由来はどうあれ、お前とその大切な夜を過ごせることが、うれしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_sleeping_3#originalText","id":"talk.vc.home_bd_alice_uw_sleeping_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"因为今天是你的生日，我就特别允许你可以偷懒吧～可以一直躺着睡在这里哦！","en":"Today's your birthday! So I'll go easy on you. You can sleep here to your heart's content.  ","ja":"今日はお前の誕生日ですだから特別に、怠惰を許しましょうずっとここで寝ていていいのですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_sleeping_4#originalText","id":"talk.vc.home_bd_alice_uw_sleeping_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"尤吉欧的生日……真想去卢利特帮他盛大地庆祝呢。","en":"It's Eugeo's birthday... So let's go to Rulid and have a big celebration!","ja":"ユージオの誕生日……ルーリッドへ行き、そこで盛大に祝いたいものですね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_sleeping_6#originalText","id":"talk.vc.home_bd_alice_uw_sleeping_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"亚丝娜的生日……要是我和你两人一起去的话，果然会很尴尬吧。","en":"It's Asuna's birthday... It wouldn't be a good idea if we went together, would it?","ja":"アスナの誕生日……私とお前、ふたりで行ったらやはりまずいでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_sleeping_7#originalText","id":"talk.vc.home_bd_alice_uw_sleeping_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"如果是你的妹妹的话，那也如同是我妹妹了，帮她盛大地庆祝吧！好了！快来帮忙。","en":"If she's your sister, then that makes her my sister too. Let's celebrate! Give me a hand!","ja":"お前の妹ならば、私の妹も同然盛大に祝いましょうほら、準備を手伝いなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_sleeping_8#originalText","id":"talk.vc.home_bd_alice_uw_sleeping_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"诗乃阁下是告诉我关于叔叔事情的重要恩人！当然要好好帮她庆祝生日！","en":"Sinon is the one who told me about my mentor. I owe her my thanks. We must celebrate her birthday! ","ja":"シノンは、私に小父様のことを伝えてくれた、大事な恩人ですその誕生日ならば祝わなければ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_sleeping_11#originalText","id":"talk.vc.home_bd_alice_uw_sleeping_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天是罗妮耶的生日呢。她喜欢些什么呀？身为前辈的你应该知道吧～","en":"Is it Ronie's birthday? What does she like? You're her senior, so surely you must know?","ja":"ロニエさんの誕生日ですか彼女の好みはなんですか?先輩なのだから知っているでしょう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_sleeping_12#originalText","id":"talk.vc.home_bd_alice_uw_sleeping_12","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"缇洁的生日，我们一起送她礼物吧！要是她能喜欢我们送的礼物就好了。","en":"Let's get a present for Tiese's birthday! I'm sure she'll be more than pleased with that!","ja":"ティーゼさんの誕生日はふたりで贈り物をしましょう喜んでくれるといいのですが"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_sleeping_14#originalText","id":"talk.vc.home_bd_alice_uw_sleeping_14","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"莉兹贝特阁下与你从同个世界过来的吧。这样的话，礼物也应该由你来选呢。","en":"Lisbeth also comes from your world, right? Then you should decide on what to give her.","ja":"リズはお前の世界からきたのですねならば、お前が贈り物を選びなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_sleeping_15#originalText","id":"talk.vc.home_bd_alice_uw_sleeping_15","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"关于西莉卡阁下的生日礼物，我们送点适合她那可爱的飞龙的礼物吧！","en":"Silica's birthday is a perfect match for that cute wyvern. Let's get her something.","ja":"シリカの誕生日はあの可愛らしい飛竜に似合う何かを贈りましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_uw_sleeping_1#originalText","id":"talk.vc.home_etc_alice_uw_sleeping_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"如果使命都已经达成的话，不需要急着起床哦，好好休息吧。","en":"If you've completed your mission, then you don't need to wake up so early. You can relax here.","ja":"使命達成したのであれば急いで起きる必要はありませんここでゆっくりしていなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_uw_sleeping_2#originalText","id":"talk.vc.home_etc_alice_uw_sleeping_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"有礼物送来了。在这里打开吧！和我在一起就没有安全问题了！","en":"The present is here! Let's open it up right here. Don't worry, you're safe if you're with me.","ja":"贈り物が届いていますここで開けてみましょう私と一緒なら安全ですから"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_uw_sleeping_3#originalText","id":"talk.vc.home_etc_alice_uw_sleeping_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"已经收到下一个使命啰。有好好养精蓄锐了吧？一起上吧！","en":"The next mission just came in. Are you well rested? If so, let's get going.","ja":"次の使命が下されました鋭気は十分に養えましたか?ならば共に行きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_pajamas_1#originalText","id":"talk.vc.home_wait_ronye_pajamas_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我可以、睡在学长旁边吗……？","en":"Is it ok... to sleep next to you?","ja":"先輩、と、隣で寝てもいいですか……?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_pajamas_2#originalText","id":"talk.vc.home_wait_ronye_pajamas_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"被摸头就会觉得很困……","en":"If you keep petting me, I'll fall asleep...","ja":"なでなでされると眠くなっちゃいます……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_pajamas_3#originalText","id":"talk.vc.home_wait_ronye_pajamas_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"哇！吓我一跳，睡意都完全消失了……","en":"Aaaah! Y-You surprised me there! My drowsiness just went away...","ja":"きゃぁっび、びっくりして眠気が吹き飛びました……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_pajamas_4#originalText","id":"talk.vc.home_wait_ronye_pajamas_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今晚请跟我一直在一起！","en":"Please stay will me all night!","ja":"今夜はずっと、一緒にいてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_pajamas_5#originalText","id":"talk.vc.home_wait_ronye_pajamas_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"呼哇……嗯……我梦到学长了。","en":"Ah... Mhm... I saw your dream.","ja":"ふわぁあぁ……ん……先輩の夢を見ていました"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_pajamas_6#originalText","id":"talk.vc.home_wait_ronye_pajamas_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"呼哇……感觉有点困呀……","en":"Ahhh... I'm getting a little sleepy...","ja":"ふあぁあぁ……なんだか眠くなってきちゃった……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_valentine_1#originalText","id":"talk.vc.home_wait_ronye_valentine_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长！我和缇洁一起做了点心。你愿意⋯⋯收下它吗⋯⋯？","en":"Hey! I made snacks with Tiese. Would you like... some...?","ja":"先輩!ティーゼとお菓子作ったんです受け取って……いただけますか……?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_valentine_2#originalText","id":"talk.vc.home_wait_ronye_valentine_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长，我最喜欢了。⋯⋯啊，欸，我是说我很喜欢吃派啦⋯⋯！","en":"I love you, Kirito ... Ah! Um, I said I love pies... !","ja":"先輩、大好き……あ、えっとパイが好きって言ったんです……!!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_valentine_3#originalText","id":"talk.vc.home_wait_ronye_valentine_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今年的冬至祭典要、要跟我一起去吗？","en":"W-Would you go to the Winter Solstice Festival, w-with me?","ja":"今年の冬至祭はわ、私と一緒に、行きませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_valentine_4#originalText","id":"talk.vc.home_wait_ronye_valentine_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"冬至祭典对女生来说是非常重要的日子喔。","en":"The Winter Solstice Festival is a very important day for women.","ja":"冬至祭は女性にとってとっても大事な日なんですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_swimsuit_1#originalText","id":"talk.vc.home_wait_ronye_swimsuit_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"其、其实我不太擅长游泳……学长，您可以教我吗……","en":"A-Actually, I can't swim... Please teach me how...","ja":"わ、わたし実は、泳ぐの苦手なんです……先輩、教えてください……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_swimsuit_1#originalText","id":"talk.vc.home_touch_ronye_swimsuit_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我、我会做更多练习的……","en":"I-I'll practice some more...","ja":"も、もっと練習します……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_swimsuit_4#originalText","id":"talk.vc.home_touch_ronye_swimsuit_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"哇！啊，对不起，只是不小心碰到了吧。","en":"Ahh! S-Sorry! It's just a scratch.","ja":"きゃっ!あっすみませんかすっただけですね"},"kind":"dialogue"},{"uid":"talk.vc.home_ronye_mc_long_bath_wait_1#originalText","id":"talk.vc.home_ronye_mc_long_bath_wait_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"最近工作结束后，最期待的事情就是去圣堂的大浴场！","en":"Lately, nothing beats going for a bath after a job!","ja":"ひと仕事終えたらカセドラルの大浴場に行くのが最近の楽しみです!"},"kind":"dialogue"},{"uid":"talk.vc.home_ronye_mc_long_bath_touch_1#originalText","id":"talk.vc.home_ronye_mc_long_bath_touch_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"头、头发还是湿的吗？","en":"Is your hair still wet?","ja":"まだ、髪が濡れてますでしょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_ronye_mc_long_bath_touch_2#originalText","id":"talk.vc.home_ronye_mc_long_bath_touch_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"最近感到骑士的胸甲有些紧绷，卸下胸甲后总会松下一口气。","en":"Wearing this breastplate all the time has been a real pain, so taking it off is such a relief.","ja":"騎士の胸当てが最近少しきつくって外すとほっとしちゃいます"},"kind":"dialogue"},{"uid":"talk.vc.home_ronye_halloween_wait_1#originalText","id":"talk.vc.home_ronye_halloween_wait_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"一起变装，然后开茶会吗？这样的话，我会和缇洁一起制作饼干带去参加的！","en":"Is it a costume party? That means I can bake some sweets with Tiese!","ja":"仮装してお茶会、ですか?それなら、ティーゼと一緒に焼き菓子を作って参ります!"},"kind":"dialogue"},{"uid":"talk.vc.home_ronye_halloween_wait_2#originalText","id":"talk.vc.home_ronye_halloween_wait_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"哇啊阿！茶会要迟到了啦～！","en":"Oh no, I'm going to be late to the party!","ja":"わわ、お茶会に遅れちゃう～!"},"kind":"dialogue"},{"uid":"talk.vc.home_ronye_halloween_touch_1#originalText","id":"talk.vc.home_ronye_halloween_touch_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"不给糖的话，我也要……捣蛋啰？","en":"I'll get tricked if I don't get any treats... right?","ja":"お菓子をくれないと私もいたずら……しちゃいますよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_1st_1#originalText","id":"talk.vc.home_wait_ronye_1st_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"打扫也是随侍重要的任务。而且我也喜欢打扫学长的房间……","en":"Cleaning your room is a crucial part of my duties as your page. And...I enjoy it, too.","ja":"お掃除も、傍付きの大事な任務です。先輩のお部屋を掃除するの、好きですし……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_1st_2#originalText","id":"talk.vc.home_wait_ronye_1st_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"虽然弟弟有时候很烦，但是这么久没见面，还是会有点想他。","en":"My little brother annoys me sometimes, but I do miss him when I'm away for too long.","ja":"弟はちょっとうるさいけど長い間会っていないと少し寂しい気もします"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_1st_3#originalText","id":"talk.vc.home_wait_ronye_1st_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"就算学长离得再远我都认得出来！因为……是学长……","en":"I can tell it's you, even from far away! I mean... because it's you...","ja":"先輩のことは、ずっと遠くからでもわかります!だって……先輩だから……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_1st_4#originalText","id":"talk.vc.home_wait_ronye_1st_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"要怎样才能像学长一样那么迅速地切入呢？下次请学长教我！","en":"How can I improve my attack speed like you? Please show me sometime!","ja":"先輩のように、速く踏み込むには、どうすればいいでしょうか今度、教えてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_1st_9#originalText","id":"talk.vc.home_wait_ronye_1st_9","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长沉思的表情是如此美好……啊！？您、您听到了吗？","en":"My mentor always looks so beautiful when he's deep in tho... Agh! D-Did you hear that?","ja":"先輩の考え事をしているお顔とってもキレイで……あっ!?き、聞こえてましたか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_1st_1#originalText","id":"talk.vc.home_touch_ronye_1st_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"芙蕾妮卡有教我怎样把头发保养得滑顺美丽……您、您觉得如何呢？","en":"Frenica taught me how to keep my hair looking nice... H-How do I look?","ja":"髪がキレイになるお手入れをフレニーカが教えてくれて……ど、どうでしょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_1st_2#originalText","id":"talk.vc.home_touch_ronye_1st_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"那个……也可以让我摸学长的头发吗？","en":"Um...may I touch your hair, too?","ja":"その……私も、先輩の髪を触らせていただいてもよろしいでしょうか……?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_1st_4#originalText","id":"talk.vc.home_touch_ronye_1st_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"呀啊！？难、难道这也是《艾恩葛朗特流》训练的一环吗？","en":"Eek?! Is th-this also a part of Aincrad Style training?","ja":"きゃっ!?こ、これも《アインクラッド流》の稽古の一環なのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_1st_5#originalText","id":"talk.vc.home_touch_ronye_1st_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"啊！是灰尘吗？谢谢学长。还帮我弄掉……","en":"Oh, did I have dust on me? Thank you for cleaning it off.","ja":"あっ、ホコリですか?ありがとうございます取ってくださって……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_1st_6#originalText","id":"talk.vc.home_touch_ronye_1st_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"为什么学长您会突然做这种事……因为是我吗？","en":"Why are you suddenly doing this...? Would you do it to any other girl?","ja":"どうして、先輩はいきなりこんなことを……私、だからですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_1st_1#originalText","id":"talk.vc.home_time_ronye_1st_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今天我准备了早餐！请务必尝尝看！","en":"I've made your breakfast today! Eat to your heart's content!","ja":"今日は私が朝ご飯をご用意いたしました!ぜひ、召し上がってください!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_1st_4#originalText","id":"talk.vc.home_time_ronye_1st_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"天气真好呢！学长，今天您不睡午觉吗？","en":"What lovely weather! Aren't you going to take a nap today, Mentor?","ja":"いいお天気ですね!先輩、今日はお昼寝しないのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_1st_7#originalText","id":"talk.vc.home_time_ronye_1st_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今晚要跟缇洁一起做神圣术的特训。因为快考试了……","en":"Tiese and I are going to practice our Sacred Arts tonight. We have a test coming up.","ja":"今日の夜はティーゼとふたりで神聖術の特訓なんですもうすぐ試験なので……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_1st_10#originalText","id":"talk.vc.home_time_ronye_1st_10","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"晚上鸦雀无声的，果然还是有点恐怖。学长，请陪伴在我身边喔。","en":"Nights are so quiet, and yet they still scare me. Won't you stay by my side?","ja":"夜はしーんとしていてやっぱり少し怖いです先輩、側にいてくださいね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_1st_1#originalText","id":"talk.vc.home_day_ronye_1st_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"就算是休假结束的隔天，只要能见到学长，我就能打起精神！","en":"Knowing I'll see you the day after a day off gives me energy! ","ja":"お休みの次の日も先輩にお会いできれば元気が出てきます!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_1st_2#originalText","id":"talk.vc.home_day_ronye_1st_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"初等练士宿舍的门禁好严苛……一不小心就会被狠狠训一顿。","en":"Curfew for primary trainees is very strict... One second late and you're in big trouble.","ja":"初等練士寮は門限が厳しくて……うっかりするとすごく怒られちゃうんです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_1st_3#originalText","id":"talk.vc.home_day_ronye_1st_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长们休假时都在聊些什么呢？我们的话……是秘密。","en":"What sorts of things do you all talk about on your days off? We talk about... No, it's a secret.","ja":"先輩たちは、お休みの日にはどんなお話をしているんですか?私たちは……秘密です"},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_1st_4#originalText","id":"talk.vc.home_day_ronye_1st_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"明天也请您不吝指教！","en":"I eagerly await your lessons tomorrow!","ja":"また明日からも、ご指導よろしくお願いいたします!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_ronye_1st_1#originalText","id":"talk.vc.home_season_ronye_1st_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我喜欢温暖的春天，不管是动物或植物，大家都会变得很有精神。","en":"I love how warm spring is. It's wonderful seeing all the plants and wild animals out and about.","ja":"春の暖かさは好きです動物も植物も、みんな元気になりますし"},"kind":"dialogue"},{"uid":"talk.vc.home_season_ronye_1st_2#originalText","id":"talk.vc.home_season_ronye_1st_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"夏天虽然很热，但在这时候玩水冲凉会很开心呢！","en":"Summers are hot, but I do love swimming on days like this.","ja":"夏は暑いですけどこんな日に水浴びするのはすごく楽しいですね!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_ronye_1st_3#originalText","id":"talk.vc.home_season_ronye_1st_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"快到收获祭时，总觉得城镇充满活力呢。要是今年也能丰收就好了。","en":"When Harvest is near, the town gets so lively. I hope this year is also bountiful.","ja":"収穫祭が近づくと、なんだか街が活気であふれますね今年も豊作だといいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_ronye_1st_4#originalText","id":"talk.vc.home_season_ronye_1st_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"只要一下雪，心情就会雀跃起来。虽然缇洁说这样好像小孩子……","en":"I always get excited when it snows. Tiese teases me for it, though. She calls me childish.","ja":"雪が降ると、わくわくしちゃうんです。ティーゼは子どもっぽいって言いますけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_uw_sleeping_1#originalText","id":"talk.vc.home_wait_ronye_uw_sleeping_1","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"其实我该称您为代表剑士大人的，但对我来说还是「学长」这个称呼比较顺口……","en":"I know I should call you \"Sir Swordsman Delegate\"...but to me, you'll always be my mentor.","ja":"本当は、代表剣士様って呼ばないとダメなんですけど、私にとってはやっぱり「先輩」なんです……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_uw_sleeping_2#originalText","id":"talk.vc.home_wait_ronye_uw_sleeping_2","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"学长还愿意教我剑术吗？就像在修剑学院的时候那样，一对一教我……","en":"Will you teach me to swordfight some more? Like back at the academy... Just the two of us...","ja":"また、私に剣を教えてくれますか?修剣学院時代みたいにふたりっきりで……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_uw_sleeping_3#originalText","id":"talk.vc.home_wait_ronye_uw_sleeping_3","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"我是学长的随侍，像这样陪在您身边是我的职责。","en":"I'm your page. Being by your side at all times is my duty.","ja":"私は先輩の傍付きだからこうしてお傍にいるのが役目なんです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_uw_sleeping_4#originalText","id":"talk.vc.home_wait_ronye_uw_sleeping_4","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"等学长要回到那边的世界时……我也能一起同行的话……我开玩笑的啦。","en":"When the time comes for you to return home to your world... I wish I could go with you...haha.","ja":"先輩がいつか、あちらの世界に帰ってしまう時……私も一緒に行けたら……なんて"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_uw_sleeping_5#originalText","id":"talk.vc.home_wait_ronye_uw_sleeping_5","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"怎、怎么觉得有点热？是因为待在学长身边的关系吗……？","en":"I-Is it just me, or is it rather hot? Perhaps it's because I'm near you...","ja":"な、なんだか暑くないですか?先輩の近くにいるのが原因でしょうか……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_uw_sleeping_6#originalText","id":"talk.vc.home_wait_ronye_uw_sleeping_6","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"从以前还在学院的时候，我就一直梦想着能像这样陪伴在学长的身边。","en":"Ever since we were in school, I've dreamed of being next to you like this.","ja":"学院時代から、ずっとこうして先輩の隣にいるのを夢見ていました"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_uw_sleeping_7#originalText","id":"talk.vc.home_wait_ronye_uw_sleeping_7","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"就只有今天，学长是属于我一个人的。到了明天，我们的关系就会回到往常的代表剑士大人和罗妮耶……","en":"Just for today, you're all mine. But tomorrow, we'll once again be the swordsman delegate and Ronie.","ja":"今日だけは、私だけの先輩です明日は、またいつもの代表剣士様とただのロニエに戻りますから……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_uw_sleeping_8#originalText","id":"talk.vc.home_wait_ronye_uw_sleeping_8","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"学长的眼神一直都很温柔……被您柔情的目光注视，我真的很幸福。","en":"Your eyes are always so kind... And when I'm in your kind gaze, I realize how truly blessed I am.","ja":"先輩の目は、いつも優しくて……その優しさに包まれていると私は幸せだなって思うんです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_uw_sleeping_9#originalText","id":"talk.vc.home_wait_ronye_uw_sleeping_9","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"学长……您睡着了吗？那我就算这么做……应该也没关系吧？","en":"Have you...fallen asleep? Then I suppose...it would be all right for me to do this.","ja":"先輩……寝ちゃいましたか?なら、こんなことしても……大丈夫、ですよね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_uw_sleeping_1#originalText","id":"talk.vc.home_touch_ronye_uw_sleeping_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"和以前相比，我的头发长了不少。请问，学长喜欢……长头发吗？","en":"My hair has grown quite a bit. So, um...do you like long hair?","ja":"前に比べて、髪はずいぶん伸びました。あの、先輩は長い髪……お好きですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_uw_sleeping_2#originalText","id":"talk.vc.home_touch_ronye_uw_sleeping_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"被学长摸头，感觉就像是回到了学院时期一样……","en":"When you pat my head like this, I feel like I'm a little kid again...","ja":"先輩にこうして頭をなでてもらうと、なんだか学院時代に戻ったみたいです……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_uw_sleeping_3#originalText","id":"talk.vc.home_touch_ronye_uw_sleeping_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我、我的脸……在发烫吗？这是因为学长摸了我的脸嘛……","en":"I-Is my face...hot? Well, that's because you're touching it...","ja":"わ、私の顔……熱いですか?それは、先輩がそうやって触るからですよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_uw_sleeping_4#originalText","id":"talk.vc.home_touch_ronye_uw_sleeping_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长的手好烫。还是其实是我的脸比较烫呢……？","en":"Your hands... They're so hot. Or perhaps it's mine that are hot.","ja":"先輩の手、すごく熱いですそれとも、私の方が熱くなっちゃってるのかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_uw_sleeping_5#originalText","id":"talk.vc.home_touch_ronye_uw_sleeping_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"和、和修剑学院的时候相比，我有成长了吗？靠自己看不太出来……","en":"H-Have I grown since my days at the academy? I can't exactly tell...","ja":"しゅ、修剣学院時代から成長しましたか?自分ではわからなくて……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_uw_sleeping_6#originalText","id":"talk.vc.home_touch_ronye_uw_sleeping_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"……这次换我帮学长放松身体。这是不是叫做按摩呢？","en":"Next time, I’ll help you relax. You call it a massage, right?","ja":"……今度は、私が先輩の体をほぐしてあげますマッサージって、いうんですよね?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_uw_sleeping_7#originalText","id":"talk.vc.home_touch_ronye_uw_sleeping_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"原来肩膀露出来了……谢谢学长的提醒，不然我差点就要感冒了。","en":"Were my shoulders exposed? Thank you... It would have been terrible to catch a cold.","ja":"肩が出てましたか……ありがとうございます風邪を引いちゃうところでした"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_uw_sleeping_8#originalText","id":"talk.vc.home_touch_ronye_uw_sleeping_8","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"每天都在训练，我的身材可能比较没那么像女孩子……","en":"Since I train every day, I suppose my figure isn't all that feminine...","ja":"毎日稽古しているから女の子っぽくないかもです私の体……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_uw_sleeping_1#originalText","id":"talk.vc.home_time_ronye_uw_sleeping_1","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"早安。呵呵，学长睡觉的表情好可爱喔。","en":"Good morning. Haha, your sleeping face was adorable.","ja":"おはようございますふふ、先輩の寝顔すごくかわいかったですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_uw_sleeping_2#originalText","id":"talk.vc.home_time_ronye_uw_sleeping_2","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"竟然能和学长一起赖床，我真的是太享受了。","en":"Look at us, sleeping in together. I feel like a spoiled princess.","ja":"先輩と一緒に朝寝坊なんてなんだかとても贅沢な気分です"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_uw_sleeping_4#originalText","id":"talk.vc.home_time_ronye_uw_sleeping_4","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"今天没有代表剑士的工作吗？那学长就一直待在这里吧。","en":"Do you not have delegate duties to tend to today? Then let's stay here together all day.","ja":"今日は、代表剣士のお仕事はお休みなんですか?なら、ずっとここにいましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_uw_sleeping_5#originalText","id":"talk.vc.home_time_ronye_uw_sleeping_5","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"在自己家里睡到中午的话会被骂。家人会要我赶快起床。","en":"My parents would always scold me if I slept in this late. \"Get up at once!\" they'd yell.","ja":"実家にいるときは、こうやってお昼まで寝てると怒られました早く起きなさいって"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_uw_sleeping_7#originalText","id":"talk.vc.home_time_ronye_uw_sleeping_7","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"晚餐就包在我身上吧！身为学长的随侍，我一定会做出美味的料理。","en":"I'll take care of supper! Your page is going to cook you a delicious feast to remember!","ja":"晩ご飯の支度はお任せください!先輩の傍付きとして、おいしいご飯をつくってみせます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_uw_sleeping_8#originalText","id":"talk.vc.home_time_ronye_uw_sleeping_8","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"听不见刀剑交锋的声响和喊叫声，和平的夜晚真的很棒。这都是多亏了学长。","en":"I just love peaceful nights without clanging swords or yelling. I have you to thank for that.","ja":"剣の音も、叫び声も聞こえない平和な夜ってステキですこれも、先輩のおかげですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_uw_sleeping_10#originalText","id":"talk.vc.home_time_ronye_uw_sleeping_10","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"我梦到学长离开了……一下下就好，能让我紧紧抱着您吗？","en":"I dreamed you left me... Can I hold you tight? Just for now...","ja":"先輩が行ってしまう夢を見て……今だけ、先輩にぎゅっと抱きついても……いいですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_uw_sleeping_11#originalText","id":"talk.vc.home_time_ronye_uw_sleeping_11","speaker":{"cn":"罗妮耶","ja":"ロニエ"},"text":{"cn":"月光透进来了。我要是也能像那样照耀学长就好了……","en":"The moonlight is so gentle. I wish I could shine on you just like that.","ja":"月の光が漏れています私も、あんな風に先輩を照らせたらいいな……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_uw_sleeping_1#originalText","id":"talk.vc.home_day_ronye_uw_sleeping_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"要开始工作了吗？代表剑士的工作肯定不容易，但还请好好加油！","en":"It's time for work again! Being the swordsman delegate sounds hard, but I believe in you!","ja":"お仕事の始まりですね代表剣士のお仕事、大変だと思いますが、頑張ってください!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_uw_sleeping_2#originalText","id":"talk.vc.home_day_ronye_uw_sleeping_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长是不是有点累了？那请在这里好好休息吧。","en":"Are you perhaps a little tired? Then please, come rest here with me.","ja":"先輩、もしかして少しお疲れですか?なら、ここで休んでください"},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_uw_sleeping_3#originalText","id":"talk.vc.home_day_ronye_uw_sleeping_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"一到安息日，整座城市都变得很热闹呢。很高兴这个世界获得和平了。","en":"The streets are so lively on Days of Rest now. I truly am happy the world is at peace.","ja":"安息日は、街が賑やかになりますね。平和な世界になって、本当に良かったです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_uw_sleeping_4#originalText","id":"talk.vc.home_day_ronye_uw_sleeping_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今天玩得好开心。等学长下次有空的时候，请再陪我出门吧。","en":"Today was so much fun! I would love to go out with you again sometime, when you're free.","ja":"今日は楽しかったですねまたお時間があったら一緒にお出かけしてください"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_1#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"能在新年刚开始就和学长在一起，今年应该会是个好年。","en":"Since I got to spend New Year's Day with you, I'm certain the rest of the year will be good.","ja":"新しい年の初めに、先輩とこうしてご一緒できたので今年は良い年になりそうです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_2#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"如果在圣堂举办撒豆子大会，感觉会很好玩耶。把城镇居民也都找来吧。","en":"A bean-throwing festival would be fun at the Cathedral. Let's invite the city-dwellers here.","ja":"豆をまく大会を、カセドラルでやったら楽しそうですね街の人も、ここに招きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_3#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"这是我为了学长所做的巧克力……您愿意吃吃看吗？","en":"I made these sweets for you... Do you like them?","ja":"先輩のために作りました私のお菓子……食べてもらえますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_4#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我家没有这种娃娃，但我父母在我成长的过程中一直都很呵护我。","en":"I never had dolls like these, but I think my mother and father still gave me a good childhood.","ja":"こういうお人形はなかったけどうちの父と母も、私のことを大事に育ててくれたと思います"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_5#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长给我的礼物……谢谢您！我可以打开来看吗？","en":"A present from you...? Thank you so much! May I open it now?","ja":"先輩からの贈り物……ありがとうございます!開けてみても、いいですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_6#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"「谎言」和「玩笑」好难区分……我真的不太懂。","en":"I can't quite distinguish between \"lies\" and \"jokes\"... It's just too difficult for me.","ja":"「嘘」と「冗談」の区別が難しくて……やっぱり、私にはよくわかりません"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_7#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"明天和后天都是安息日……希望在这段期间内，能和学长有很多相处时间。","en":"Today and the day after are Days of Rest...I'm so happy I get to be with you all that time.","ja":"明日もあさっても安息日……その間、先輩とたくさん一緒にいられたら……うれしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_8#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_8","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"不知为什么，一下雨就会想起学院时期的事情。比如说在雨声中背诵术式的情景……","en":"When it rains, I remember my schooldays. Like, memorizing arts while listening to the rain...","ja":"雨が降ると、なぜか学院時代を思い出すんです。雨の音の中で術式を暗記した思い出とか……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_9#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_9","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"要是能够多制造一点白麻纸，让大家都能把愿望写上去就好了。","en":"I hope we can manufacture enough hemp paper for everyone to write down their wishes.","ja":"みんなが願い事を書けるくらい白麻紙がたくさん作れるようになるといいですね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_10#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_10","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"一听到夏至祭典的音乐，真的会忍不住兴奋起来。学长，我们还是赶紧出门吧！","en":"When I hear Summer Festival music, it always makes me excited. Come, let's go to the festival!","ja":"夏至祭の音楽を聴くとやっぱりワクワクしちゃいます先輩、やっぱりお出かけしましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_11#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_11","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"夏季假期也差不多结束了，今年夏天，和学长一起留下了许多很棒的回忆。","en":"Our summer vacation has come to an end. I made so many wonderful memories with you this year.","ja":"夏期休暇も、これで終わりです今年の夏は、先輩とたくさん思い出を作ることができました"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_12#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_12","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"剑名和龙的名字都是取自月亮……所以我对露那利亚大人特别有亲近感。","en":"Since my sword and dragon are both named after the moon...I feel much closer to Lunaria now.","ja":"剣の銘も、竜の名前も月にちなんでいるので……ルナリア様が前より身近に感じます"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_13#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_13","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"亚丝娜大人准备了很多糖果，孩子们肯定都会很开心！","en":"Lady Asuna prepared a wide variety of candies for the children. I know they'll love it!","ja":"アスナ様が、たくさんのお菓子を用意してくださいました子どもたちに喜んでもらえますね!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_ronye_uw_sleeping_15#originalText","id":"talk.vc.home_event_ronye_uw_sleeping_15","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"趁人睡觉的时候悄悄将礼物留下来，那位先生真是亲切呀。","en":"Santa must be a very kind old man, to leave presents on children's pillows while they sleep.","ja":"寝ている間にそっと贈り物を置いていくなんて、その方はとても親切なんですね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_uw_sleeping_2#originalText","id":"talk.vc.home_bd_ronye_uw_sleeping_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"……学长居然送我生日礼物，我从来没有这么开心过！","en":"A birthday present from my mentor... Oh, I couldn't possibly be any happier!","ja":"……先輩から誕生日の贈り物なんて、こんなにうれしいことはありません!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_uw_sleeping_3#originalText","id":"talk.vc.home_bd_ronye_uw_sleeping_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"生日快乐。学长，您有想要的东西吗？只要是能力所及，我什么都愿意做……","en":"Happy Birthday! Is there anything you'd like? I would give you anything...","ja":"お誕生日、おめでとうございます先輩、欲しいものありますか?できることなら、私、なんでも……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_uw_sleeping_4#originalText","id":"talk.vc.home_bd_ronye_uw_sleeping_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今天是尤吉欧学长生日。这一整天就请学长在这里告诉我两位之间的故事吧。","en":"It's Eugeo's birthday, I see. I would love to stay here all day and hear stories about you two.","ja":"ユージオ先輩のお誕生日ですね今日はここでずっと、先輩たちのお話、聞かせてください"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_uw_sleeping_5#originalText","id":"talk.vc.home_bd_ronye_uw_sleeping_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"不如把爱丽丝大人的生日也订为这个世界的纪念日吧？学长觉得这个主意怎样？","en":"Do you suppose we should make Lady Alice's birthday a holiday in this world?","ja":"アリス様のお誕生日はこちらの世界でも記念日にするのはいかがでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_uw_sleeping_6#originalText","id":"talk.vc.home_bd_ronye_uw_sleeping_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"亚丝娜大人的生日我打算送厨具。我已经找到很可爱的了。","en":"I will give Lady Asuna cooking tools for her birthday. I found some really cute ones.","ja":"アスナ様のお誕生日はお料理の道具を贈りますかわいい物が見つかったので"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_uw_sleeping_7#originalText","id":"talk.vc.home_bd_ronye_uw_sleeping_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今天是《绿之剑士》莉法小姐的生日。我一直都很想见她一面。","en":"Today is the Green Swordswoman Leafa's birthday. I wish I could have met her.","ja":"《緑の剣士》リーファさんのお誕生日ですね一度お会いしたかったです"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_uw_sleeping_8#originalText","id":"talk.vc.home_bd_ronye_uw_sleeping_8","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"诗乃小姐是索鲁斯大人的化身……是不是举办祭典庆祝比较好呢？","en":"Since Sinon is the goddess Solus incarnate...perhaps we should throw her a festival?","ja":"シノンさんはソルス様の化身だから……やはりお祭りをした方がよいでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_uw_sleeping_12#originalText","id":"talk.vc.home_bd_ronye_uw_sleeping_12","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"缇洁的生日，我们会两人一起庆祝。就算是学长也不能来喔。","en":"I want to celebrate Tiese's birthday alone with her. I won't even let you come.","ja":"ティーゼの誕生日はふたりでお祝いしますいくら先輩でも来たらダメですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_uw_sleeping_14#originalText","id":"talk.vc.home_bd_ronye_uw_sleeping_14","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"莉兹贝特小姐是冶炼师吧？那我觉得还是送稀有的矿石会比较好。","en":"Lisbeth is a blacksmith, yes? Then perhaps we should give her some rare metal ore.","ja":"リズベットさんは、鍛冶師ですよねなら、やはり珍しい鉱石などを贈るのがいいと思います"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_ronye_uw_sleeping_15#originalText","id":"talk.vc.home_bd_ronye_uw_sleeping_15","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"西莉卡小姐的话，我想送她那头可爱的飞龙喜欢吃的东西。","en":"For Silica's birthday, I think want to get her a treat for her cute little dragon.","ja":"シリカさんには、あのかわいい飛竜が好きそうなご飯を贈りたいと思っています"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_ronye_uw_sleeping_1#originalText","id":"talk.vc.home_etc_ronye_uw_sleeping_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"达成使命，辛苦了。今天就请好好休息，别太勉强自己了。","en":"A job well done, sir. Please, rest and recuperate here. Let me take care of you.","ja":"使命達成、お疲れ様でした今日は無理せずに、ここで休養をとってください"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_ronye_uw_sleeping_2#originalText","id":"talk.vc.home_etc_ronye_uw_sleeping_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"有要给学长的礼物送到了。讲师已经确认过，里面没有危险物品。","en":"You've received a gift. Don't worry—I've checked it to make sure it's nothing dangerous.","ja":"贈り物が届いています危険な物がないかどうか師範が確認されていました"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_ronye_uw_sleeping_3#originalText","id":"talk.vc.home_etc_ronye_uw_sleeping_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"下一个工作要去哪呢？如果比较远的话，请让我以随侍的身分与学长同行！","en":"Where is your next mission? If it's far away, please allow me to accompany you as your page!","ja":"次のお仕事はどこですか?遠くに行くなら、傍付きとして同行させていただきます!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_tiese_valentine_1#originalText","id":"talk.vc.home_wait_tiese_valentine_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长！我和罗妮耶一起做了点心⋯⋯希望合你口味⋯⋯","en":"Eugeo! I made snacks with Ronie... I hope it suits your taste...","ja":"先輩! ロニエと一緒にお菓子を作ったんです……お口に合うとよいのですが……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_tiese_valentine_2#originalText","id":"talk.vc.home_wait_tiese_valentine_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长⋯⋯喜、喜欢⋯⋯的食物是什么呢？","en":"Eugeo… I love… I'd love to know your favorite food. Can you tell me?","ja":"先輩……す、好き……な食べ物はなんですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_tiese_valentine_3#originalText","id":"talk.vc.home_wait_tiese_valentine_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学、学长今年冬至祭典有什么事吗？如果没有的话，可以和我⋯⋯","en":"E-Eugeo, do you have any plans for the Winter Solstice Festival? If you're free, how about me and you...","ja":"せ、先輩は今年の冬至祭ご予定ありますか?よろしければ、私と一緒に……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_tiese_valentine_4#originalText","id":"talk.vc.home_wait_tiese_valentine_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我从以前开始就常常在冬至祭典的时候做点心。这种事，我很擅长喔！","en":"Long ago, I used to bake sweets when it was the Winter Solstice Festival. That was my specialty!  ","ja":"冬至祭の時は昔からよく焼き菓子を作っていましたそういうの、得意なんです!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_tiese_swimsuit_1#originalText","id":"talk.vc.home_wait_tiese_swimsuit_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我很擅长游泳喔！学长，需要我教您吗？","en":"I'm pretty good at swimming! Do you want me to teach you how?","ja":"あたし、けっこう泳ぐの得意なんです!先輩、教えて差し上げましょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_swimsuit_1#originalText","id":"talk.vc.home_touch_tiese_swimsuit_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"要不要把头发扎起来呢……","en":"I wonder if I should tie up my hair...","ja":"髪、結ぼうかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_swimsuit_4#originalText","id":"talk.vc.home_touch_tiese_swimsuit_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"哇！啊，那个，有没有弄湿您的衣服？","en":"Ahh! M-My clothes didn't get wet, did they?","ja":"きゃっ!あ、あの、お洋服濡れませんでした?"},"kind":"dialogue"},{"uid":"talk.vc.home_tiese_halloween_wait_1#originalText","id":"talk.vc.home_tiese_halloween_wait_1","speaker":{"cn":"缇洁","ja":"ティーゼ"},"text":{"cn":"扮装后一起去茶会感觉会很开心！","ja":"仮装してお茶会だなんてなんだか楽しそうですね!"},"kind":"dialogue"},{"uid":"talk.vc.home_tiese_halloween_wait_2#originalText","id":"talk.vc.home_tiese_halloween_wait_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"为了今天的茶会，我和罗妮耶一起烤了饼干。请好好期待吧。","en":"I baked some treats with Ronie for today's tea! Hope you like 'em!","ja":"今日のお茶会のためにロニエと焼き菓子を作ったんです楽しみにしててくださいね"},"kind":"dialogue"},{"uid":"talk.vc.home_tiese_halloween_wait_3#originalText","id":"talk.vc.home_tiese_halloween_wait_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"快要到茶会的时间了。","en":"Tea time, everyone!","ja":"そろそろお茶会の時間ですね"},"kind":"dialogue"},{"uid":"talk.vc.home_tiese_contest_wait_1#originalText","id":"talk.vc.home_tiese_contest_wait_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，要不要和我一起跳舞呢？","en":"Eugeo, care to dance with me?","ja":"先輩、あたしと躍りませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_tiese_contest_wait_2#originalText","id":"talk.vc.home_tiese_contest_wait_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"就算跳得不是很好也没关系。只要能和学长牵着手跳舞就已经……","en":"You don't have to be a pro. As long as I can just hold your hand and dance...","ja":"上手く踊れなくてもいいんです先輩と手を繋いで踊れたらそれだけで……"},"kind":"dialogue"},{"uid":"talk.vc.home_tiese_contest_touch_1#originalText","id":"talk.vc.home_tiese_contest_touch_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"头发我是请罗妮耶帮我打理的，和平常的发型相比，学长你喜欢哪一种呢？","en":"I had Ronie do my hair. It's different from my usual style, but which do you prefer?","ja":"髪はロニエに結ってもらいましたいつもの髪型と、先輩はどっちが好きですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_tiese_mc_bath_wait_1#originalText","id":"talk.vc.home_tiese_mc_bath_wait_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"在圣堂的澡堂泡澡时，偶尔可以听到从男生浴池传来的说话声，令人有些脸红心跳。","en":"I occasionally hear people talking in the men's bath whenever I go for a dip. It's kinda exciting...","ja":"カセドラルのお風呂に入っているとたまに、男湯の話し声が聞こえて少しドキドキします"},"kind":"dialogue"},{"uid":"talk.vc.home_tiese_mc_bath_touch_1#originalText","id":"talk.vc.home_tiese_mc_bath_touch_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"因为罗妮耶的头发长长了，前阵子，是我帮她洗了头的哦！","en":"Ronie's hair got longer, so last time I helped wash her hair.","ja":"ロニエの髪が伸びたからこないだ、あたしが洗ってあげたんですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_tiese_mc_bath_touch_2#originalText","id":"talk.vc.home_tiese_mc_bath_touch_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"任务结束，卸下胸前的装备后，心情也会放松下来。","en":"Taking this armor off after a mission is the best part of the day.","ja":"任務を終えて胸の装備を外すと気持ちもゆったりします"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_tiese_1st_1#originalText","id":"talk.vc.home_wait_tiese_1st_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长今天也要特训吗？不介意的话，请让我一起参与吧！","en":"Mentor, training again today? I would be honored if I could join you!","ja":"先輩、今日も特訓ですか?よろしければ、あたしも一緒にやらせてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_tiese_1st_2#originalText","id":"talk.vc.home_wait_tiese_1st_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"虽然《艾恩葛朗特流》与过往教过的剑术不同，但是很利于战斗。","en":"Aincrad Style is different from any technique I've learned, but it's very intuitive.","ja":"《アインクラッド流》はこれまで教わった剣とは違いますけどとても戦いやすいです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_tiese_1st_3#originalText","id":"talk.vc.home_wait_tiese_1st_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"不少上级贵族在城镇中一样目中无人……真希望他们能收敛一点。","en":"Higher-rank nobles are arrogant, even when they're in public... You should be more careful.","ja":"上級貴族は、街でも傍若無人の方が多く……もう少し弁えていただきたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_tiese_1st_4#originalText","id":"talk.vc.home_wait_tiese_1st_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"希望学长哪天能跟父亲见个面，相信父亲会和学长聊得很高兴的。","en":"I'd love for you to meet my father someday. I just know he would love chatting with you.","ja":"先輩には、いつか父に会っていただきたいです。きっと父は先輩と話すのが楽しいと思うんです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_tiese_1st_9#originalText","id":"talk.vc.home_wait_tiese_1st_9","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，慢慢来没关系的！像这样在学长身旁待命也是随侍的工作！","en":"You can take it slow, Mentor. Supporting you like this is a page's duty.","ja":"先輩、ゆっくりで大丈夫ですよこうして先輩の側に控えるのが傍付きの役目ですから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_1st_1#originalText","id":"talk.vc.home_touch_tiese_1st_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"那、那个……因为才刚结束训练，所以……有流汗……还请不要……","en":"Um, I j-just finished...training... so I'm, um, sweaty... and I'd rather you not...","ja":"あ、あの……稽古を終えたばかりで、その……汗が……なので、あまり……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_1st_2#originalText","id":"talk.vc.home_touch_tiese_1st_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长的话没关系。因为摸着我头发的那只手很温柔……","en":"I don't mind if you touch my hair, Mentor. Your touch is... gentler than the others.","ja":"先輩なら、いいですあたしの髪を撫でてくださるその手、やさしいから……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_1st_4#originalText","id":"talk.vc.home_touch_tiese_1st_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"虽、虽然很痒，但学长觉得可以的话，我……","en":"Th-That tickles! But if you insist, I don't mind...","ja":"く、くすぐったいですけど先輩がいいなら、あたしは……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_1st_5#originalText","id":"talk.vc.home_touch_tiese_1st_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"被学长如此对待让我心跳加速……感觉胸口快炸裂了。","en":"My heart races when you do that to me... I feel like it's going to explode.","ja":"先輩にそうされると胸がドキドキして……破裂してしまいそうです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_1st_6#originalText","id":"talk.vc.home_touch_tiese_1st_6","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长您……比想像中还要大胆呢。","en":"Mentor... You're much more... forward than I took you for.","ja":"……先輩は、思ったよりも大胆……なのですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_1st_1#originalText","id":"talk.vc.home_time_tiese_1st_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"一早就能见到学长，感觉今天一整天都能过得很快乐呢！","en":"Seeing you first thing in the morning makes me feel like it's going to be a fun day!","ja":"今日は朝から先輩に会えて一日とっても楽しく過ごせそうです!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_1st_4#originalText","id":"talk.vc.home_time_tiese_1st_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天的午餐想跟学长们还有罗妮耶四个人一起吃呢……","en":"I was thinking all four of us could have dinner together tonight.","ja":"今日のお昼ご飯は先輩たちとロニエと4人で食べたいなって……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_1st_7#originalText","id":"talk.vc.home_time_tiese_1st_7","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天罗妮耶陪我一起练习。我不是很擅长神圣术……","en":"Ronie is going to help me study today. I'm not very good at Sacred Arts.","ja":"今日は、あたしの勉強にロニエが付き合ってくれるんです神聖術は、少し苦手で……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_tiese_1st_10#originalText","id":"talk.vc.home_time_tiese_1st_10","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"这么晚了还外出，学长您也挺大胆的呢。不过我是很开心啦……","en":"Taking me out at night like this... You're rather bold, Mentor. Though I'm glad you did.","ja":"こんな夜にお出かけなんて先輩も少し大胆ですね……あたしは、うれしいですけど"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_1st_1#originalText","id":"talk.vc.home_day_tiese_1st_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我要在之后的训练中学会《艾恩葛朗特流》的剑技！","en":"Starting today, I vow to master at least one move from the Aincrad Style!","ja":"今日からの稽古で《アインクラッド流》の技をひとつ身につけます!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_1st_2#originalText","id":"talk.vc.home_day_tiese_1st_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"观察学长的技术也是训练的一部分……我知道了！之后我会好好观察的！","en":"Watching is part of the learning process... Understood! I'll gladly watch you for the next two days!","ja":"先輩の技を見るのも稽古の一環……わかりました!今日と明日は、見させて頂きます!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_1st_3#originalText","id":"talk.vc.home_day_tiese_1st_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"下次休假时要跟室友一起到镇上逛街。我会买点东西给您的！","en":"The next Day of Rest, I'll be going to town with my roommates. I'll buy you something nice!","ja":"今度のお休みは、部屋のみんなで街に行くんですお土産、買ってきますね!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_1st_4#originalText","id":"talk.vc.home_day_tiese_1st_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"休假时要是熬夜，隔天就会很辛苦呢。真的该睡了……","en":"Staying up late the night after a Day of Rest makes the next day difficult. I need to go to bed.","ja":"お休みの夜に夜更かしすると明日が辛いですよねもう寝ないと……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_1st_1#originalText","id":"talk.vc.home_season_tiese_1st_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"啊，学长请看！长出小小的对生双叶了。真可爱呢……","en":"Ooh, look at this, Mentor! What cute little buds...","ja":"あっ、見てください先輩!小さな双葉が出てきてますかわいいなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_1st_2#originalText","id":"talk.vc.home_season_tiese_1st_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，您就算大热天制服还是穿得很整齐呢。就是这种地方……让我很尊敬。","en":"You always wear your uniform impeccably, even when it's hot. I...really respect that about you.","ja":"先輩は、暑くても制服を着崩さないんですねそういうところ……尊敬します"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_1st_3#originalText","id":"talk.vc.home_season_tiese_1st_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"秋天的空气有着独特的味道呢，一股清新让人感觉很舒服。","en":"Autumn skies have a special scent to them. Very crisp and comforting.","ja":"秋の空気は、独特の匂いがしますね。すごく澄んでいて気持ちがいいです"},"kind":"dialogue"},{"uid":"talk.vc.home_season_tiese_1st_4#originalText","id":"talk.vc.home_season_tiese_1st_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"总觉得水会结成冰很不可思议呢。明明就没有用神圣术……","en":"How fascinating, the way water can freeze to ice. All without Sacred Arts...","ja":"水が氷に変わるってなんだか不思議ですね神聖術も使わないのに……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_1st_1#originalText","id":"talk.vc.home_wait_administrator_1st_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"永恒不变的世界正是我的理想，这个世界根本不需要改变。","en":"A static world for all eternity. That is my utopia. Change is not necessary.","ja":"永遠に変わらない世界それが私の理想なの変化なんて必要ないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_1st_2#originalText","id":"talk.vc.home_wait_administrator_1st_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"裘迪鲁金这男人虽然无可救药，但绝不会违抗我，所以我才把他安排在身边。","en":"Chudelkin is a hopeless man, but he never defies me. That is why I keep him close.","ja":"チュデルキンは度しがたい男だけど、決して私に逆らわないだからあの男を側に置くの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_1st_3#originalText","id":"talk.vc.home_wait_administrator_1st_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"没错，爱是何等尊贵啊。人们为了追求它，宁可抛下其他的一切。","en":"Yes, love is precious. People will abandon everything else once they attain it.","ja":"ええ、愛は尊い物よみんな、それさえ手に入ればほかの全てを投げ打ってしまう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_1st_4#originalText","id":"talk.vc.home_wait_administrator_1st_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"为什么要去想多余的事呢……明明不去思考才是幸福啊。","en":"Why must your mind wander where it shouldn't? Life is much easier when you don't think.","ja":"どうして余計なことを考えるのかしら……考えなければ幸福でいられるのに"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_1st_9#originalText","id":"talk.vc.home_wait_administrator_1st_9","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你还愣在那做什么？不是有事要报告吗？","en":"Why do you look so stunned? Perhaps you just learned some shocking information?","ja":"何を呆けた顔をしているのなにか、報告があるのではなくて?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_1st_1#originalText","id":"talk.vc.home_touch_administrator_1st_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"那手是怎么回事？真没办法，再做一次「调整」好了。","en":"Is your hand malfunctioning? Very well, allow me to give it another adjustment.","ja":"その手は何かしら?しょうがないわね、もう一度「調整」を施しましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_1st_2#originalText","id":"talk.vc.home_touch_administrator_1st_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"没错，我的容貌再也不会受时间侵蚀，永远维持这身模样。","en":"Time will not ravage my body. I shall remain eternally in my current beautiful form.","ja":"ええ、もはや時間は私の姿を犯すことはできない永遠にこの姿を保つの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_1st_4#originalText","id":"talk.vc.home_touch_administrator_1st_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你还真是索求无度呢，真有这么饥渴吗？","en":"You seem quite ravenous. Are you really that starved?","ja":"ずいぶん欲しがるのねそんなに飢えているの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_1st_5#originalText","id":"talk.vc.home_touch_administrator_1st_5","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"我讨厌穿着衣服，紧贴着肌肤的触感让我烦躁难耐……","en":"I dislike wearing clothes. The cloth is so rough against my skin.","ja":"服を着るのは嫌いなのよ肌にまとわりつくのが鬱陶しくて……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_1st_6#originalText","id":"talk.vc.home_touch_administrator_1st_6","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"真是不敬……你以为我会一直宽容下去吗？","en":"Your impudence is intolerable. Just how far do you think my mercy will stretch?","ja":"……無礼ね、あなた私がいつまでも慈悲の心を持つと思って?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_1st_1#originalText","id":"talk.vc.home_time_administrator_1st_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"现在是……早上？拜托没事别叫我起床。","en":"Is it...morning already? If you have no business, then let me sleep.","ja":"今は……朝なの?用事がないなら起こさないで頂戴"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_1st_4#originalText","id":"talk.vc.home_time_administrator_1st_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"索鲁斯之光……若是那东西也在我支配之下，便能消除这刺眼的光芒了。","en":"Solus... If only Solus were under my control, then I could extinguish this harsh light.","ja":"ソルスの光……あれも私の支配下におければこの強い光を消してあげるのに"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_1st_7#originalText","id":"talk.vc.home_time_administrator_1st_7","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"夜晚是暗之民的时间，去告诉集成骑士们多加注意。","en":"Night is a time for evil. Tell the Integrity Knights to be vigilant.","ja":"夜は闇の輩の時間整合騎士たちに注意するよう言っておきなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_1st_10#originalText","id":"talk.vc.home_time_administrator_1st_10","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"真安静呢，要是能一直这样该有多好。","en":"Very quiet indeed. How wonderful the world would be if it were quiet like this forever.","ja":"静かねずっとこうならどんなに素晴らしいことか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_1st_1#originalText","id":"talk.vc.home_day_administrator_1st_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你应该有任务在身才是，那还在这里磨蹭什么？","en":"I gave you a mission. So why are you here?","ja":"あなたには任務を与えたはずそれなのに、ここで何をしているの?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_1st_2#originalText","id":"talk.vc.home_day_administrator_1st_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"根本不需要什么军队，只要有集成骑士跟我的力量在……你说是吧？","en":"I need no army. The Integrity Knights and my own powers are more than sufficient.","ja":"軍隊なんて必要ないわ整合騎士と、それに私の力があれば……ね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_1st_3#originalText","id":"talk.vc.home_day_administrator_1st_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"民众在安息日活动会变得频繁，多留意有没有人违反禁忌目录吧。","en":"The peasants become rowdy on Days of Rest. Watch out for those who break the Taboo Index.","ja":"安息日には民衆の動きが活発になるわ。禁忌目録の違反者がいないか、注意なさい"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_1st_4#originalText","id":"talk.vc.home_day_administrator_1st_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"睡不着吗？你们不需要思考也可以啊……","en":"You can't sleep? Then stop thinking. Your kind don't need to think.","ja":"眠れないの?……考え事なんてしなくていいのよ、あなたたちは"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_1st_1#originalText","id":"talk.vc.home_season_administrator_1st_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"春天神圣力高涨，这季节做研究再适合不过了。","en":"Sacred Power increases in the spring. It is a season ideal for experimentation.","ja":"春は神聖力が高まるのもし研究をするならこの季節がいいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_1st_2#originalText","id":"talk.vc.home_season_administrator_1st_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"为了生活舒适，圣堂里面做了调整，这点热没什么大不了的。","en":"I have organized the Cathedral for comfort. It was nothing but child's play for me.","ja":"カセドラルの中は、快適に過ごせるよう調整しているのこのくらい、たやすいことよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_1st_3#originalText","id":"talk.vc.home_season_administrator_1st_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"摇曳的麦穗……看到就觉得莫名地怀念。这是为什么呢？","en":"The wheat is blowing in the wind... I am not sure why, but this feels familiar to me.","ja":"麦の穂が揺れている……どうしてかしらね、不思議と懐かしいような気持ちがするわ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_administrator_1st_4#originalText","id":"talk.vc.home_season_administrator_1st_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"才想说怎么这么静，原来是下雪了……在这种日子泡澡很舒服呢。","en":"It's snowing... I thought it was oddly quiet. A bath on a day like this would certainly feel nice.","ja":"静かだと思ったら、雪……こんな日はお風呂が気持ちいいでしょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_uw_sleeping_1#originalText","id":"talk.vc.home_wait_administrator_uw_sleeping_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"欢迎你，来吧。你想要的东西，这里一样都不会少的。","en":"Come to me, my dear child. I have everything your heart desires right here.","ja":"さあ、いらっしゃいあなたの欲しいものならここにちゃんと用意してあるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_uw_sleeping_2#originalText","id":"talk.vc.home_wait_administrator_uw_sleeping_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你不需要思考，只要听我的命令行事就可以了。","en":"You needn't think about anything. Just listen to my voice.","ja":"あなたは何も考えなくていいの私の言うことを聞いていればそれだけで十分なのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_uw_sleeping_3#originalText","id":"talk.vc.home_wait_administrator_uw_sleeping_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你现在幸福吗？当然幸福了，对吧？呵呵、呵呵呵……","en":"Let me ask, are you happy? You must be happy, yes? Hehe, hehehe...","ja":"あなたは今、幸せかしら?もちろん幸せよねふふ、ふふふ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_uw_sleeping_4#originalText","id":"talk.vc.home_wait_administrator_uw_sleeping_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你不用再去追寻了，想要爱的话我给你，由我来满足你心中渴望吧。","en":"Your search is over. I shall give you all the love you need. Let me fill the emptiness inside you.","ja":"もう何も探さなくていいわ愛なら私が与えてあげるあなたの中を、私で満たしなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_uw_sleeping_5#originalText","id":"talk.vc.home_wait_administrator_uw_sleeping_5","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你该感到荣幸，照理来说你是根本不可能和我同床共枕的。","en":"You should feel honored. Sleeping beside me is a nigh unattainable experience.","ja":"光栄に思いなさい私としとねを共にできるなど本来あり得ないことなのだから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_uw_sleeping_6#originalText","id":"talk.vc.home_wait_administrator_uw_sleeping_6","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"把你的一切献给我，来，你是不是越来越想这么做了？牵起我的手吧……","en":"Offer everything unto me. I know you want to. So, come, take my hand.","ja":"あなたのすべてを差し出すのほら、そうしたくなってきたでしょうさあ、この手を取って……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_uw_sleeping_7#originalText","id":"talk.vc.home_wait_administrator_uw_sleeping_7","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"今天你想看什么就尽情看吧。虽然我不晓得你明天是否还会记得就是了。","en":"You may watch as long as you wish today. Though I can't guarantee you'll remember anything tomorrow.","ja":"今日は、好きなだけ見てかまわないわ明日になっても覚えていられるかはわからないけど"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_uw_sleeping_8#originalText","id":"talk.vc.home_wait_administrator_uw_sleeping_8","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"来，闭上眼。接着，用心去感受……呵呵，是不是很有快感？","en":"Now, close your eyes. Sharpen your other senses. Hehe... Doesn't it feel exhilarating?","ja":"ほら、目を閉じなさいそして、感覚を研ぎ澄ませば……ふふ、快感でしょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_uw_sleeping_9#originalText","id":"talk.vc.home_wait_administrator_uw_sleeping_9","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"没错，沉眠吧。当你醒来时，肯定又会是那个「幸福」的你。","en":"Good. Let sleep take you. When you wake, you shall have returned to your former blissful state.","ja":"そう、お眠りなさい目が覚めた時にはきっとまた「幸福」なあなたに戻っているから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_uw_sleeping_1#originalText","id":"talk.vc.home_touch_administrator_uw_sleeping_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你很在意我的头发呢。我就特别准许你摸吧。这是今天才有的犒赏喔。","en":"Does my hair interest you? Then you may touch it. Just this once. It's your reward.","ja":"私の髪が気になるのねなら、触れることを許しましょう今日だけのご褒美よ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_uw_sleeping_2#originalText","id":"talk.vc.home_touch_administrator_uw_sleeping_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"为我的美貌痴迷是无可奈何……但你有点太不客气了呢。","en":"Entranced by my face? Well... I don't blame you, but you must exercise a little restraint.","ja":"私の顔に魅入るのは仕方のないことだけど……少し無遠慮が過ぎるわね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_uw_sleeping_3#originalText","id":"talk.vc.home_touch_administrator_uw_sleeping_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你认为自己可以随意碰我？你真这么想的话可以试试看。","en":"You think I'll let you touch me? Then try it, if you dare.","ja":"触っても許されると思うの?許されると思うなら、触りなさいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_uw_sleeping_4#originalText","id":"talk.vc.home_touch_administrator_uw_sleeping_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"想要我牵起你的手是吗？好啊，如你所愿，接着我会赐予你一切。","en":"You wish to hold my hand? Very well, I shall hold your hand and give everything to you.","ja":"手を取ってほしいのねええ、握ってあげるわそしてすべてを与えてあげる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_uw_sleeping_5#originalText","id":"talk.vc.home_touch_administrator_uw_sleeping_5","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"呵呵，你的欲望显露出来了呢。你那再怎么渴求，都不会满足的欲望……呵呵呵……","en":"Haha...somebody's certainly full of desire. A desire that cannot be quenched... Hehehe.","ja":"ふふ、欲望があふれているわどんなにもがいても満たされない欲望が……ふふふ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_uw_sleeping_6#originalText","id":"talk.vc.home_touch_administrator_uw_sleeping_6","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你渴望我是吗？那就完成你的使命吧。","en":"You wish to take me, do you not? Well, you must complete your mission first.","ja":"私を貪りたいのね?なら、その前に使命を果たしなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_uw_sleeping_7#originalText","id":"talk.vc.home_touch_administrator_uw_sleeping_7","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"没错，将手放在这里。维持好这个姿势……然后，咏唱我刚才教你的式句。","en":"Yes. Place your hand there. Firmly. And now...recite the incantation I just taught you.","ja":"そう、ここに手を当ててしっかり、そのまま……そしてさっき教えた式句を唱えなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_administrator_uw_sleeping_8#originalText","id":"talk.vc.home_touch_administrator_uw_sleeping_8","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"真是粗鲁啊。既然你如此饥渴，那肯定能为我所用。","en":"My! So savage. If you are really that starved, I am confident you will serve me well.","ja":"乱暴なのねそんなに飢えているのならきっと私の役に立ってくれるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_1#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"我要稍微休息一下。我破例赐予你也能在这里休息的权利。","en":"I am going to rest for a while. As a special reward, I shall allow you to lay beside me.","ja":"私はもう少し休むわ特別に、あなたにもここで休む権利を与えてあげる"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_2#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"今天准备烤甜面包给我。没什么特别的理由，我就只是想吃而已。","en":"Fetch me some cakes. I've no particular reason why, but I crave them today.","ja":"今日は甘焼きパンを用意して特に理由はないけれど食べたくなったのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_4#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"今天这个房间，谁也进不来，是只属于我和你的空间喔。","en":"Today, I shall let no one else enter this room. It will be a special place for you and me.","ja":"この部屋には、今日は誰も入れない私とあなただけの空間よ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_5#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_5","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"调整前的奖励我就慷慨一点吧。反正你也不会记得。","en":"I'll indulge you with a special reward before I readjust you. You'll forget about it anyway.","ja":"調整前のご褒美くらいは奮発してあげましょうかどうせ忘れてしまうけれど"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_7#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_7","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"又得整理记忆了……就算那个恼人的元老长来了，你也要确实将他赶走。","en":"I must arrange my memories again. If that pesky Prime Senator comes, make sure you drive him away.","ja":"また記憶の整理をしないと……あのうるさい元老長が来てもきちんと追い返すように"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_8#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_8","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"裘迪鲁金献上了少见的葡萄酒，你就陪我一下吧。","en":"Chudelkin brought me an unusual wine. Come drink it with me.","ja":"珍しいワインをチュデルキンが持ってきたから、少し私に付き合いなさいな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_10#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_10","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"大家都已经睡着了呢。那是不是到了给你「爱」的时间了呢？","en":"Everyone has gone to sleep. I suppose this means it is time for me to give you my love.","ja":"もうみんな寝静まったわねなら、あなたに「愛」をあげる時間かしら"},"kind":"dialogue"},{"uid":"talk.vc.home_time_administrator_uw_sleeping_11#originalText","id":"talk.vc.home_time_administrator_uw_sleeping_11","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"把灯关掉……没错，你不觉得黑暗更宁静，更让人感到舒适吗？","en":"Turn off those troublesome lights... Good. Doesn't it feel much nicer in the dark?","ja":"明かりを消して……そう真っ暗な方が、煩わしくなくて気分がいいでしょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_uw_sleeping_1#originalText","id":"talk.vc.home_day_administrator_uw_sleeping_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"好了，你今天去运行任务吧。回来之后，要确实到这里跟我回报，听到了吗？","en":"Now, go attend to your mission today. I expect you to report to me immediately upon your return.","ja":"さあ、今日は任務に行きなさい帰ってきたら、きちんとここで報告をするように、ね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_uw_sleeping_2#originalText","id":"talk.vc.home_day_administrator_uw_sleeping_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"人界今天也一如既往呢。这正是我所期望的。","en":"Just another ordinary day in the Human Empire. As it should be.","ja":"今日も人界はいつもと変わらないわねそれこそ、私が望むことよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_administrator_uw_sleeping_3#originalText","id":"talk.vc.home_day_administrator_uw_sleeping_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"安息日再怎么喧闹，也不会吵到这里来。如此安静真叫人心情舒畅。","en":"The Day of Rest's bustle does not reach us up here, which is what I prefer. I like the peace and quiet.","ja":"安息日の賑々しさもここまでは届かないわね静かなのは心地いいわ"},"kind":"dialogue"}]};
